quiz.answer:
declare const require: any; // 標準入力を読むための宣言(消さない)
const input: string = require("fs").readFileSync(0, "utf8");
const lines: string[] = input.split("\n").filter((l: string) => l.trim() !== "");

interface Product {
  id: number;
  name: string;
  price: number;
  description?: string;
}

function label(product: Product): string {
  const base = `${product.name}：${product.price}円`;
  if (product.description) {
    return `${base}(${product.description})`;
  }
  return base;
}

for (const line of lines) {
  const [id, name, price, description] = line.split(",");
  const product: Product = { id: Number(id), name, price: Number(price) };
  if (description) {
    product.description = description;
  }
  console.log(label(product));
}

