declare const require: any; // 標準入力を読むための宣言(消さない)
const input: string = require("fs").readFileSync(0, "utf8");
const lines: string[] = input.split("\n").filter((l: string) => l.trim() !== "");

// any をやめて、引数に正しい型を書く
function format(data: any): string {
  return data.toFixed(1);
}

for (const line of lines) {
  console.log(format(line));
}

quiz.answer:
declare const require: any; // 標準入力を読むための宣言(消さない)
const input: string = require("fs").readFileSync(0, "utf8");
const lines: string[] = input.split("\n").filter((l: string) => l.trim() !== "");

function format(data: number): string {
  return data.toFixed(1);
}

for (const line of lines) {
  console.log(format(Number(line)));
}
